item.content:encoded:
body #masthead.site-header {
    border-top: 4px solid #EE346A;
}
.no-border .jobmate_job_filters {
    border: none !important;
}
select#search_categories {
    font-size: 13px;
    text-transform: capitalize;
    letter-spacing: 0.5px;
    color: #999 !important;
}

